-- Add every non-empty fact from the supplied sixth batch. Russian/Russia
-- content is soft-hidden with isActive rather than deleted, preserving data
-- and historical delivery records for a future editorial re-enable.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (479, $$Построение нейронных связей: Ученые из Университета Эмори (США) доказали с помощью МРТ, что чтение художественной литературы физически увеличивает количество связей в левой височной коре (зоне, отвечающей за язык) и центральной борозде мозга (отвечающей за моторику).$$),
  (480, $$Эффект «мышечной памяти» мозга: Нейронные изменения, вызванные прочтением захватывающей книги, сохраняются в мозге в течение нескольких дней после того, как вы закрыли последнюю страницу.$$),
  (481, $$Активация соматосенсорной коры: Когда вы читаете описание физических действий (например, «герой побежал»), мозг активирует те же участки коры, которые включились бы, если бы вы побежали в реальности.$$),
  (482, $$Улучшение белого вещества: Исследования Стэнфордского университета показали, что регулярное чтение укрепляет белое вещество мозга, улучшая проводимость сигналов между его отделами.$$),
  (483, $$Тренировка когнитивного резерва: Чтение создает резерв прочности в мозге, помогая ему компенсировать физические повреждения или возрастные изменения без потери функций.$$),
  (484, $$Синхронизация полушарий: Чтение требует одновременной работы левого полушария (анализ букв и слов) и правого (визуализация образов), что укрепляет мозолистое тело.$$),
  (485, $$Увеличение объема серого вещества: Продольные исследования доказывают, что у читающих людей плотность серого вещества в областях, связанных с памятью и обучением, выше, чем у нечитающих.$$),
  (486, $$Развитие зоны Брока и зоны Вернике: Чтение напрямую стимулирует эти ключевые области, отвечающие за восприятие и воспроизведение речи, делая вашу собственную речь более плавной.$$),
  (487, $$Стимуляция зрительной коры: Чтение текста активирует затылочные доли мозга гораздо сильнее, чем просмотр видеоконтента, так как мозг сам декодирует символы в образы.$$),
  (488, $$Эффект «глубокого погружения»: Нейробиологи называют чтение процессом «глубокого внимания» (deep attention), который кардинально отличается от «поверхностного внимания» (hyper attention) при скроллинге соцсетей.$$),
  (489, $$Защита от Альцгеймера: Исследование, опубликованное в журнале Neurology, доказало, что у людей, постоянно тренирующих мозг чтением, риск развития болезни Альцгеймера снижается в 2,5 раза.$$),
  (490, $$Продление жизни на 2 года: Ученые из Йельского университета (исследование с участием 3600 человек в течение 12 лет) выяснили, что люди, читающие книги более 3,5 часов в неделю, живут в среднем на 23 месяца дольше тех, кто не читает вообще.$$),
  (491, $$Замедление когнитивного увядания: Регулярное чтение в пожилом возрасте снижает скорость возрастной потери памяти и умственных способностей на 32%.$$),
  (492, $$Снижение риска деменции: Клиника Мэйо подтвердила, что чтение книг, разгадывание кроссвордов и компьютерные игры в зрелом возрасте снижают риск развития умеренных когнитивных нарушений на 30–50%.$$),
  (493, $$Нейропластичность в старости: Чтение заставляет мозг постоянно формировать новые синапсы, сохраняя его пластичность (способность адаптироваться) вплоть до глубокой старости.$$),
  (494, $$Снижение уровня кортизола: Чтение эффективно подавляет выработку гормона стресса кортизола, избыток которого разрушает иммунную систему и сосуды.$$),
  (495, $$Нормализация артериального давления: Ученые доказали, что 30 минут тихого чтения снижают систолическое и диастолическое давление так же эффективно, как и легкая йога.$$),
  (496, $$Профилактика инсультов: Поддержание высокой активности мозга с помощью чтения укрепляет сосудистую сетку мозга и снижает риск ишемических поражений.$$),
  (497, $$Снижение хронического воспаления: За счет общего подавления стресс-реакций организма чтение помогает снизить маркеры хронического воспаления (например, С-реактивный белок).$$),
  (498, $$Психологическая защита при онкологии: Библиотерапия официально признана ВОЗ как поддерживающий элемент терапии, улучшающий выживаемость пациентов за счет снижения уровня депрессии и тревожности.$$),
  (499, $$Снижение стресса на 68%: Исследование Университета Суссекса (Великобритания) показало, что всего 6 минут чтения при полной концентрации снижают уровень стресса на 68%. Это эффективнее прогулки (42%), чашки чая (54%) или прослушивания музыки (61%).$$),
  (500, $$Успокоение пульса: Шестиминутное чтение замедляет частоту сердечных сокращений и снимает мышечное напряжение.$$),
  (501, $$Эффективное снотворное: Чтение бумажной книги перед сном подает организму сигнал о переходе в режим отдыха, формируя здоровый ритуал засыпания.$$),
  (502, $$Вред экранов (E-reading): Чтение со смартфона или планшета перед сном из-за синего спектра света блокирует выработку мелатонина на 50%, ухудшая фазу глубокого сна. Бумажные книги этого не делают.$$),
  (503, $$Борьба с тревожными расстройствами: Чтение художественной литературы переключает мозг с «внутренней жвачки» (руминации — постоянного прокручивания тревожных мыслей) на внешний сюжет.$$),
  (504, $$Лечение легкой депрессии: Британские врачи официально имеют право выписать рецепт на «чтение определенных книг» (программа Books on Prescription) для пациентов с легкой и умеренной депрессией.$$),
  (505, $$Развитие эмоциональной устойчивости: Сталкиваясь с трудностями героев в книгах, человек подсознательно прорабатывает собственные психологические травмы.$$),
  (506, $$Снижение уровня агрессии: Чтение активирует префронтальную кору, которая отвечает за контроль импульсов и торможение агрессивных реакций.$$),
  (507, $$Эффект медитации: Чтение длинных текстов вводит мозг в состояние альфа-волн, схожее с состоянием во время глубокой медитации или осознанного транса.$$),
  (508, $$Повышение уровня счастья: Опросы Кембриджского университета показали, что люди, регулярно читающие книги, на 20% чаще чувствуют удовлетворенность своей жизнью.$$),
  (509, $$Развитие эмпатии: Ученые из Новой школы социальных исследований в Нью-Йорке доказали, что чтение качественной художественной литературы (Literary Fiction) резко повышает способность понимать чувства других людей.$$),
  (510, $$«Теория разума» (Theory of Mind): Чтение развивает способность человека моделировать чужое психическое состояние — понимать, что у другого человека есть свои мотивы, отличные от твоих.$$),
  (511, $$Распознавание чужих эмоций: Читающие люди точнее определяют эмоции окружающих по выражению лица и микромимике (тест «Чтение мыслей по глазам»).$$),
  (512, $$Снижение предвзятости: Чтение книг о представителях других рас, религий или социальных групп статистически снижает уровень ксенофобии и стереотипного мышления у читателя.$$),
  (513, $$Улучшение навыков родительства: Читающие родители более склонны к диалогу с детьми и реже применяют методы физического или агрессивного психологического наказания.$$),
  (514, $$Повышение качества брака: Совместное чтение и обсуждение книг укрепляют эмоциональную связь между супругами и снижают количество разводов.$$),
  (515, $$Развитие харизмы: Богатый словарный запас и начитанность делают человека более привлекательным собеседником, повышая его социальный статус в группе.$$),
  (516, $$Понимание мотивов оппонента: В бизнесе и переговорах читающие люди лучше прогнозируют шаги контрагентов за счет развитого навыка анализа мотивов литературных персонажей.$$),
  (517, $$Снижение чувства одиночества: Книга выступает в качестве «социального суррогата» — мозг воспринимает общение с персонажами как реальный социальный контакт, что спасает от изоляции.$$),
  (518, $$Улучшение альтруистического поведения: Психологические тесты показывают, что люди, только что прочитавшие главу книги, с большей вероятностью помогут незнакомцу, чем те, кто листал ленту новостей.$$),
  (519, $$Расширение кристаллизованного интеллекта: Чтение напрямую увеличивает объем кристаллизованного интеллекта — запаса знаний и фактов, который человек накапливает в течение жизни.$$),
  (520, $$Словарный запас: Чтение — главный источник редких и сложных слов. Читающий человек сталкивается с лексикой, которая на 50% реже используется в разговорной речи или на телевидении.$$),
  (521, $$Эффект Матфея в образовании: Дети, которые начинают читать рано, быстрее развивают общий интеллект (IQ), что создает накопительный эффект превосходства во всех школьных дисциплинах, включая математику.$$),
  (522, $$Улучшение рабочей памяти: Чтобы следить за сюжетом, мозг вынужден удерживать в оперативной памяти десятки деталей: имена, локации, предыстории персонажей. Это тренирует гиппокамп.$$),
  (523, $$Развитие аналитического мышления: Любители детективов подсознательно решают логические задачи по ходу чтения, что улучшает навык поиска паттернов в реальной жизни.$$),
  (524, $$Концентрация внимания: Чтение книги требует длительного удержания фокуса на одном объекте, что является лучшей защитой от «клипового мышления» и синдрома дефицита внимания (СДВГ).$$),
  (525, $$Улучшение навыков письма: Механическое восприятие правильно построенных текстов автоматически улучшает грамотность и пунктуацию читателя за счет зрительной памяти.$$),
  (526, $$Повышение пространственного мышления: Описание локаций, архитектуры и перемещений героев заставляет мозг строить сложные 3D-модели в пространственной памяти.$$),
  (527, $$Развитие критического мышления: Чтение разных авторов с противоположными точками зрения учит мозг сопоставлять факты и распознавать манипуляции и фейки.$$),
  (528, $$Улучшение академической успеваемости: Исследование Centre for Longitudinal Studies (Великобритания) показало, что чтение книг ради удовольствия имеет большее значение для успеваемости ребенка, чем уровень образования его родителей.$$),
  (529, $$Связь чтения и дохода: Исследование Университета Падуи показало, что дети, выросшие в домах с большими библиотеками, во взрослом возрасте зарабатывают в среднем на 21% больше своих сверстников, росших без книг.$$),
  (530, $$Лидерские качества: 85% успешных топ-менеджеров и миллиардеров (включая Билла Гейтса, Уоррена Баффета и Илона Маска) читают не менее 1–2 книг в неделю.$$),
  (531, $$Повышение креативности: Чтение расширяет ассоциативный ряд, позволяя находить нестандартные решения бизнес-задач на стыке разных дисциплин.$$),
  (532, $$Улучшение навыков презентации: Благодаря развитой лексике читающие люди четче формулируют свои мысли, реже используют слова-паразиты и увереннее защищают проекты перед инвесторами.$$),
  (533, $$Снижение когнитивной гибкости к ошибкам: Читающие руководители статистически реже совершают логические ошибки при стратегическом планировании.$$),
  (534, $$Быстрое освоение новых профессий: Навык работы с длинными текстами позволяет быстрее осваивать сложную техническую документацию и менять квалификацию.$$),
  (535, $$Тайм-менеджмент: Чтение требует выделения регулярных слотов времени, что подсознательно тренирует навыки самодисциплины и планирования дня.$$),
  (536, $$Защита от профессионального выгорания: Переключение внимания на художественную литературу после работы дает мозгу полноценный отдых, предотвращая эмоциональное истощение.$$),
  (537, $$Повышение культурного капитала: Знание классической и современной литературы облегчает нетворкинг и выстраивание связей в высокоранговых социальных кругах.$$),
  (538, $$Увеличение настойчивости (Grit): Чтение длинных трудов (например, романов-эпопей) приучает мозг к отложенному вознаграждению, что помогает доводить до конца сложные рабочие проекты.$$),
  (539, $$Развитие речи с младенчества: Младенцы, которым родители читают книги вслух с 6 месяцев, к моменту поступления в школу имеют словарный запас на 40% выше нормы.$$),
  (540, $$Формирование безопасной привязанности: Чтение родителями книги вслух ребенку перед сном снижает уровень детской тревожности и укрепляет базовое доверие к миру.$$),
  (541, $$«Эффект 30 миллионов слов»: Дети из семей, где принято много читать и разговаривать, к 4 годам слышат на 30 миллионов слов больше, чем дети из нечитающих семей, что предопределяет их интеллектуальное превосходство.$$),
  (542, $$Развитие воображения: В отличие от мультфильмов, где образы уже даны в готовом виде, книга заставляет мозг ребенка самостоятельно генерировать визуальный ряд, развивая фантазию.$$),
  (543, $$Улучшение самоконтроля: Дети, умеющие долго сидеть за книгой, показывают более высокие результаты в знаменитом «зефирном тесте» (способность контролировать импульсивные желания).$$),
  (544, $$Профилактика подростковой депрессии: Подростки, имеющие привычку читать книги, легче переживают гормональные кризисы и реже склонны к деструктивному поведению.$$),
  (545, $$Повышение эмпатии у детей: Чтение сказок, где четко разделены мотивы добра и зла, помогает формированию базовых морально-этических ориентиров.$$),
  (546, $$Подготовка к школе: Чтение книг формирует у дошкольника навык усидчивости, необходимый для адаптации к урокам.$$),
  (547, $$Расширение кругозора: Книги знакомят ребенка с концепциями (космос, история, микромир), с которыми он не может столкнуться в повседневном быту.$$),
  (548, $$Улучшение сна у детей: Замена вечерних гаджетов на чтение книги снижает детские ночные кошмары и гиперактивность перед сном.$$),
  (549, $$Снижение частоты приступов мигрени: У людей с хроническими головными болями чтение в тишине снижает интенсивность болевого синдрома за счет расслабления мышц шеи и лица.$$),
  (550, $$Профилактика близорукости (при правильном свете): Вопреки мифам, чтение при качественном освещении и соблюдении дистанции в 35–40 см тренирует цилиарную мышцу глаза, предотвращая её спазм.$$),
  (551, $$Правило 20-20-20: Врачи рекомендуют каждые 20 минут чтения смотреть в течение 20 секунд на объект в 20 футах (6 метрах) от вас, что является идеальной гимнастикой для зрения.$$),
  (552, $$Нормализация дыхания: Глубокое погружение в чтение выравнивает ритм дыхания, делая вдох и выдох более глубокими, что улучшает насыщение крови кислородом.$$),
  (553, $$Снижение психосоматических болей: Чтение действует как легкий анальгетик: мозг настолько концентрируется на сюжете, что блокирует слабые болевые сигналы, идущие от тела.$$),
  (554, $$Повышение качества восстановления после спорта: Чтение книги после тяжелой физической тренировки переводит вегетативную нервную систему из состояния симпатики (бей или беги) в парасимпатику (отдых и восстановление).$$),
  (555, $$Улучшение осанки (при контроле позы): Чтение за конторкой (стоя) или на правильном стуле укрепляет мышцы кора и шеи.$$),
  (556, $$Снижение тяги к перееданию: Чтение занимает руки и мозг, эффективно борясь с «эмоциональным перееданием» от скуки или стресса.$$),
  (557, $$Защита от синдрома сухого глаза (по сравнению с ПК): При чтении бумажной книги человек моргает в 2–3 раза чаще, чем при взгляде на светящийся монитор компьютера, что сохраняет слезную пленку.$$),
  (558, $$Улучшение координации движений: За счет стимуляции моторной коры при чтении экшен-сцен поддерживается общий тонус двигательных нейронов.$$),
  (559, $$Формирование личной идентичности: Книги помогают человеку ответить на экзистенциальные вопросы и сформировать собственную систему ценностей.$$),
  (560, $$Повышение толерантности к двусмысленности: Начитанные люди легче переносят неопределенность в жизни и не ищут простых (черно-белых) ответов на сложные жизненные вопросы.$$),
  (561, $$Развитие эстетического вкуса: Восприятие красивого слога и метафор формирует внутреннее чувство гармонии и стиля.$$),
  (562, $$Увеличение открытости новому опыту (Openness to Experience): Согласно психологическим тестам «Большой пятерки», активные читатели имеют высокие баллы по шкале открытости новому.$$),
  (563, $$Снижение уровня эгоцентризма: Постоянное пребывание «в головах» других персонажей разрушает иллюзию того, что мир вращается только вокруг вас.$$),
  (564, $$Улучшение навыков саморефлексии: Чтение заставляет человека проецировать поступки героев на свою жизнь и анализировать собственное поведение.$$),
  (565, $$Повышение экологической осознанности: Чтение научно-популярной литературы о природе увеличивает бережное отношение к окружающей среде.$$),
  (566, $$Обретение смысла жизни: Литература выступает как вековой опыт человечества, помогающий справиться с кризисом среднего возраста и экзистенциальной пустотой.$$),
  (567, $$Развитие интуиции: Большой багаж прочитанных жизненных сценариев позволяет подсознанию быстрее выдавать правильные интуитивные решения в реальности.$$),
  (568, $$Снижение страха смерти: Чтение философской и глубокой художественной литературы помогает примириться с конечностью бытия.$$),
  (569, $$Оптимальное время чтения: Научно доказано, что минимальный порог для запуска терапевтического эффекта чтения составляет 15–20 минут в день.$$),
  (570, $$Художественная литература против Нон-фикшн: Для развития эмпатии и снижения стресса эффективнее работает художественная литература. Нон-фикшн развивает только фактологические знания.$$),
  (571, $$Польза перечитывания: Повторное прочтение великих книг спустя годы активирует новые зоны мозга, так как вы накладываете текст на свой изменившийся жизненный опыт.$$),
  (572, $$Чтение вслух: Чтение вслух улучшает дикцию, память и слуховое восприятие информации, задействуя речедвигательный аппарат.$$),
  (573, $$Принцип «Активного чтения»: Делать пометки на полях, выписывать цитаты и подчеркивать мысли (маргиналии) увеличивает усвояемость информации на 60% по сравнению с пассивным чтением.$$),
  (574, $$Бумага против аудио: Мозг усваивает информацию из бумажной книги и аудиокниги примерно одинаково, но бумажная книга лучше развивает пространственную память (вы помните, где именно на странице был написан факт).$$),
  (575, $$Разнообразие жанров: Смена жанров (сегодня — фантастика, завтра — биография, послезавтра — стихи) предотвращает когнитивную адаптацию и держит мозг в тонусе.$$),
  (576, $$Обсуждение прочитанного: Обсуждение книги в книжном клубе или с друзьями запускает процесс «социального когнитивного моделирования», удваивая пользу для интеллекта.$$),
  (577, $$Идеальное расстояние: Оптимальное расстояние от глаз до книги для предотвращения близорукости составляет Гарвардский стандарт — 40 сантиметров.$$),
  (578, $$Лучшая инвестиция в себя: С точки зрения нейробиологии, чтение — это самый дешевый, доступный и эффективный способ продлить молодость мозга и сохранить ясность ума до глубокой старости.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  'LITERATURE',
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;

-- Do not delete this content: pause every editorial card about Russia,
-- Russian authors, Russian-language vocabulary, the USSR, or Soviet history.
-- The Lily selector already requires isActive = true, so the change takes
-- effect immediately for new facts while remaining fully reversible.
UPDATE "philology_facts"
SET "isActive" = FALSE, "updatedAt" = CURRENT_TIMESTAMP
WHERE "isActive" = TRUE
  AND "text" ~* '(росси|русск|ссср|советск|большевик|петроград|кремл|сталин|пастернак|достоевск|толст|пушкин|гогол|лермонтов|чехов|есенин|маяковск|тургенев|некрасов|гумилев|ахматов|мандельштам|зощенко|салтыков|жуковск|грибоедов|булгаков|бунин|куприн|горьк|фет|фонвизин|тютчев|жданов|солженицын|стругацк|ильф|петров|набоков|чуковск|крылов|беляев|акунин|гайдар|блок|волошин|бендер|ппш|живаго|облонск|мюнхгаузен)';

